2	/** Moves the claim to the action's status, refusing a change its current status does not allow.
3	 *  Opening gives the claim its number (see {@link ClaimNumbering}), which it keeps when voided. Settling fixes the claim's
4	 *  due at the person's grade's rate in force on the claim's date (none when there is none, so it stays live).
5	 *  A claim a statement binds is settled at its bound figure. An overdue claim's late charge is frozen in on top.
6	 *  Both are rounded by the claim's rounding (see {@link PolicyDate}).
7	 *  The user who opened a claim may not settle it (four eyes).
8	 *  Only a steward approves or rejects a PENDING claim, and never the user who opened it approves it. Approving
9	 *  fixes the due at its live figure of that moment (a PENDING claim is not bound by a statement), late charge
10	 *  frozen in; rejecting needs a reason and moves the claim back to OPEN, bound again by its statement.
11	 *  Publishes the number the audit line carries. */
12	public class ApplyClaimAction {
13	    public void apply(@Val ClaimAction action, @Val Claim claim, ClaimNumbering numbering,
14	            PersonRepository people, RateRepository rates, Floor floor, LatePct latePct, PolicyDate policyDate,
15	            RoleRepository roles, Out<ClaimNumber> numberOut,
16	            @RequestParam(value = "user", required = false) String user,
17	            @RequestParam(value = "reason", required = false) String reason)
18	            throws InvalidClaimStatusException {
19	        if (!action.allowedFrom(claim.getStatus())) {
20	            throw new InvalidClaimStatusException(
21	                    "A " + claim.getStatus() + " claim cannot be moved to " + action.to() + ".");
22	        }
23	        if (action == ClaimAction.SETTLE && claim.getOpenedBy() != null && claim.getOpenedBy().equals(user)) {
24	            throw new InvalidClaimStatusException("The user who opened a claim cannot settle it.");
25	        }
26	        if ((action == ClaimAction.APPROVE || action == ClaimAction.REJECT)
27	                && !Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), user))) {
28	            throw new InvalidClaimStatusException("Only a steward can " + action.name().toLowerCase(Locale.ROOT)
29	                    + " a PENDING claim.");
30	        }
31	        if (action == ClaimAction.APPROVE && claim.getOpenedBy() != null && claim.getOpenedBy().equals(user)) {
32	            throw new InvalidClaimStatusException("The user who opened a claim cannot approve it.");
33	        }
34	        if (action == ClaimAction.REJECT && (reason == null || reason.isBlank())) {
35	            throw new InvalidClaimStatusException("A reason is needed to reject a claim.");
36	        }
37	        // The late charge is worked out while the claim is still OPEN (or PENDING), so settling freezes it in.
38	        boolean fixes = action == ClaimAction.SETTLE || action == ClaimAction.APPROVE;
39	        RoundingMode mode = !fixes ? null : policyDate.of(claim.getSheetId()).modeFor(claim);
40	        BigDecimal settledDue = !fixes ? null : latePct.of(claim.getSheetId())
41	                .addTo(claim, claim.isBound() ? claim.getStatedDue() : dueNow(claim, people, rates, floor, mode), mode);
42	        claim.setStatus(action.to());
43	        switch (action) {
44	            case OPEN -> {
45	                claim.setNumber(numbering.next(claim));
46	                claim.setOpenedBy(user);
47	            }
48	            case SETTLE, APPROVE -> claim.setSettledDue(settledDue);
49	            default -> { }
50	        }
51	        numberOut.set(new ClaimNumber(claim.getNumber()));
52	    }
53	    /** amount × pct / 100, rounded by {@code mode} to two decimals and at least the floor; null when no rate is in force on the claim's date. */
54	    private static BigDecimal dueNow(Claim claim, PersonRepository people, RateRepository rates, Floor floor, RoundingMode mode) {
55	        Person person = people.findById(claim.getSheetId(), claim.getPersonId());
56	        return Floor.raise(claim, Rate.inForce(rates.findBySheet(claim.getSheetId()), person.gradeOn(claim.getDate()), claim.getDate())
57	                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, mode))
58	                .orElse(null), floor.of(claim.getSheetId()));
59	    }
60	}
