169	/** Opens each selected claim in list order (people in the order they were added, each person's claims
170	 *  newest first), so their numbers follow that order. Each is opened by the same rules, and writes the same
171	 *  audit lines and status log line, as opening it alone; one those rules refuse (or not on the sheet) is left as it is. */
172	public class BulkOpenClaims {
173	    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenRequest request,
174	            @RequestParam(value = "user", required = false) String user, ClaimRepository claims,
175	            PersonRepository people, PeriodRepository periods, RateRepository rates, Floor floor, LatePct latePct,
176	            PolicyDate policyDate, ClaimNumbering numbering, RoleRepository roles, Rollup rollup, ClaimLog log, Audit audit, Out<BulkOpenResult> resultOut) {
177	        Set<Long> selected = new HashSet<>(request.claimIds());
178	        List<Claim> sheetClaims = claims.findBySheet(sheetId);
179	        List<Claim> ordered = new ArrayList<>();
180	        for (Person person : people.findBySheet(sheetId)) {
181	            for (Claim claim : sheetClaims) {
182	                if (claim.getPersonId() == person.getId() && selected.contains(claim.getId())) ordered.add(claim);
183	            }
184	        }
185	        int opened = 0;
186	        for (Claim claim : ordered) {
187	            Rollup.Snapshot before = rollup.take(sheetId);
188	            ClaimNumber[] number = new ClaimNumber[1];
189	            try {
190	                new CheckClaimActionOpen().check(claim, periods);
191	                new ApplyClaimAction().apply(ClaimAction.OPEN, claim, numbering, people, rates, floor, latePct, policyDate,
192	                        roles, n -> number[0] = n, user, null);
193	            } catch (InvalidClaimStatusException refused) {
194	                continue;
195	            }
196	            claims.save(claim);
197	            log.record(claim, user);
198	            new AuditClaimStatus().audit(ClaimAction.OPEN, claim, number[0], user, null, people, audit);
199	            rollup.changes(sheetId, user, before, rollup.take(sheetId)).forEach(audit::record);
200	            opened++;
201	        }
202	        resultOut.set(new BulkOpenResult(opened, selected.size() - opened));
203	    }
204	}
