757	public class ValidateClaim {
758	    /** Any amount, with up to two decimals; a negative one is a correction. */
759	    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
760	    /** A claim number: a sheet-wide one (1 or more), or one within a period (<period name>-<n>, X-<n> in none). */
761	    private static final Pattern NUMBER = Pattern.compile("(.+-)?\\d{1,9}");
762	    public void validate(@RequestBody ClaimRequest request, Out<ValidClaim> body) throws InvalidClaimException {
763	        body.set(of(request));
764	    }
765	    /** The claim form's rules, shared with the quick-add bar. A correction (a negative amount) must name the
766	     *  number of the claim it corrects, and only a correction may; whether that claim is a SETTLED claim of
767	     *  the same person is checked once the person is known (see {@link Correction}). */
768	    static ValidClaim of(ClaimRequest request) throws InvalidClaimException {
769	        String amount = request == null || request.amount() == null ? "" : request.amount().strip();
770	        String date = request == null || request.date() == null ? "" : request.date().strip();
771	        String note = request == null || request.note() == null ? "" : request.note();
772	        String corrects = request == null || request.corrects() == null ? "" : request.corrects().strip();
773	        if (amount.isEmpty()) {
774	            throw new InvalidClaimException("An amount is required.");
775	        }
776	        if (!AMOUNT.matcher(amount).matches()) {
777	            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
778	        }
779	        LocalDate parsed = null;
780	        if (!date.isEmpty()) {
781	            try {
782	                parsed = LocalDate.parse(date);
783	            } catch (DateTimeParseException e) {
784	                throw new InvalidClaimException("Not a valid date.");
785	            }
786	        }
787	        BigDecimal value = new BigDecimal(amount).setScale(2);
788	        String number = null;
789	        if (value.signum() < 0) {
790	            if (corrects.isEmpty()) {
791	                throw new InvalidClaimException("A negative amount is a correction: name the number of the settled claim it corrects.");
792	            }
793	            boolean sheetWide = corrects.chars().allMatch(Character::isDigit);
794	            if (!NUMBER.matcher(corrects).matches() || (sheetWide && Integer.parseInt(corrects) < 1)) {
795	                throw new InvalidClaimException("The claim a correction corrects must be named by its number.");
796	            }
797	            number = sheetWide ? String.valueOf(Integer.parseInt(corrects)) : corrects;
798	        } else if (!corrects.isEmpty()) {
799	            throw new InvalidClaimException("Only a claim with a negative amount corrects another claim.");
800	        }
801	        return new ValidClaim(value, parsed, note, number);
802	    }
803	}
