195	        for (Claim claim : claims.findByPerson(sheetId, person.getId())) {
196	            boolean counts = claim.getStatus().isOpen() || claim.getStatus() == ClaimStatus.SETTLED;
197	            if (counts && !person.counts(claim)) {
198	                continue;           // an unbound OPEN or PENDING claim dated within a hold: in no total, and left as it is
199	            } else if (!counts) {
200	                claim.setStated(false);
201	                claim.setStatedDue(null);
202	            } else {
203	                RoundingMode mode = policy.modeFor(claim);
204	                BigDecimal figure = figure(claim, person, rates, least, mode);
205	                if (figure != null) figured = true;
206	                BigDecimal due = late.addTo(claim, figure, mode);
207	                if (due != null) sum = sum.add(due);
208	                claim.setStated(true);
209	                claim.setStatedDue(figure);
210	                counted++;
211	            }
212	            claims.save(claim);
213	        }
214	        BigDecimal dueTotal = Rate.inForce(rates, person.gradeOn(today), today).isEmpty() && !figured ? null : sum;
215	        person.setStatementCount(person.getStatementCount() + 1);
216	        person.setStatedTotal(dueTotal);
217	        person.setStatementDate(today);
218	        people.saveStatement(person);
219	        statementOut.set(new Statement(dueTotal, counted));
220	    }
221	    /** amount × pct / 100, rounded by {@code mode} to two decimals and at least the floor, unless already fixed; null when n/a. */
222	    private static BigDecimal figure(Claim claim, Person person, List<Rate> rates, BigDecimal least, RoundingMode mode) {
223	        if (claim.getSettledDue() != null) return claim.getSettledDue();
224	        if (claim.isBound()) return claim.getStatedDue();
225	        return Floor.raise(claim, Rate.inForce(rates, person.gradeOn(claim.getDate()), claim.getDate())
226	                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, mode))
227	                .orElse(null), least);
228	    }
229	}
