291	/** The sheet's late percent (two decimals, 0.00 until set). An overdue claim (OPEN or PENDING, its due-by — fixed
292	 *  when it was created, see {@link Terms} — before the sheet's today) gains the late percent of its figure for every full
293	 *  30 days it is overdue, rounded to two decimals by the claim's rounding (see {@link PolicyDate}), on top. The charge is never bound by a
294	 *  statement; settling freezes it into the settled due. A correction (a negative amount) has no late charge. */
295	@Service
296	public class LatePct {
297	    public static final String KEY = "late-pct";
298	    public static final String DEFAULT = "0.00";
299	    private final SettingRepository settings;
300	    private final SheetClock clock;
