310	    public record Charge(BigDecimal pct, LocalDate today) {
311	        /** The figure with the claim's late charge, rounded by {@code mode}, on top; null (n/a) stays null. */
312	        public BigDecimal addTo(Claim claim, BigDecimal figure, RoundingMode mode) {
313	            if (figure == null || !claim.getStatus().isOpen() || claim.isCorrection()) return figure;
314	            long late = ChronoUnit.DAYS.between(claim.getDueBy(), today);
315	            if (late <= 0) return figure;
316	            long periods = late / 30;
317	            return figure.add(figure.multiply(pct).multiply(BigDecimal.valueOf(periods))
318	                    .divide(BigDecimal.valueOf(100), 2, mode));
319	        }
320	    }
