204	        this(id, sheetId, name, grade, version, 0, null, null);
205	    }
206	    public Person(long id, String sheetId, String name, String grade, long version, int statementCount,
207	            BigDecimal statedTotal, LocalDate statementDate) {
208	        this.id = id;
209	        this.sheetId = sheetId;
210	        this.name = name;
211	        this.grades.add(new DatedGrade(grade, null));
212	        this.version = version;
213	        this.statementCount = statementCount;
