221	    /** The person's grades, each in force from its from-date, earliest first (the first one from the
222	     *  beginning of time). */
223	    public List<DatedGrade> getGrades() { return grades; }
224	    public void setGrades(List<DatedGrade> grades) {
225	        this.grades = new ArrayList<>(grades);
226	        this.grades.sort(Comparator.comparing(DatedGrade::from, Comparator.nullsFirst(Comparator.naturalOrder())));
227	    }
