229	    public String gradeOn(LocalDate date) {
230	        String grade = grades.get(0).grade();
231	        for (DatedGrade dated : grades) {
232	            if (dated.from() == null || !dated.from().isAfter(date)) grade = dated.grade();
233	        }
234	        return grade;
235	    }
