237	    public void gradeFrom(String grade, LocalDate from) {
238	        List<DatedGrade> next = new ArrayList<>(grades);
239	        next.removeIf(dated -> from.equals(dated.from()));
240	        next.add(new DatedGrade(grade, from));
241	        setGrades(next);
