264	    public List<String> getPatrons() { return patrons; }
265	    public void setPatrons(List<String> patrons) { this.patrons = new ArrayList<>(patrons); }
266	    /** Whether this claim of the person counts in the live totals: SETTLED, and OPEN or PENDING unless
267	     *  it is dated within one of their holds and not bound by a statement. */
268	    public boolean counts(Claim claim) {
269	        ClaimStatus status = claim.getStatus();
270	        if (status == ClaimStatus.SETTLED) return true;
271	        if (!status.isOpen()) return false;
272	        return claim.isBound() || holds.stream().noneMatch(hold -> hold.covers(claim.getDate()));
273	    }
