864	/**
865	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
866	 * so tests can assert side-effects by reading that file — the second test-assertion channel
867	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
868	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
869	 *
870	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
871	 * SYNC) so a test reads the record immediately.
872	 */
873	@Service
874	public class Audit {
875	    private final Path file;
876	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
877	        this.file = Path.of(path);
878	    }
879	    /** Append one audit record. Tests assert the exact line(s) in the file. */
880	    public synchronized void record(String entry) {
881	        try {
882	            Path parent = file.toAbsolutePath().getParent();
883	            if (parent != null) {
884	                Files.createDirectories(parent);
885	            }
886	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
887	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
888	        } catch (IOException e) {
889	            throw new UncheckedIOException(e);
890	        }
891	    }
892	    /** Remove the audit file. */
893	    public synchronized void clear() {
894	        try {
895	            Files.deleteIfExists(file);
896	        } catch (IOException e) {
897	            throw new UncheckedIOException(e);
898	        }
899	    }
900	}
